package com.healthwise.analysis.controller;import com.healthwise.analysis.dto.AnalysisDtos.*;import com.healthwise.analysis.service.AnalysisService;import com.healthwise.security.CurrentUser;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/analysis")public class AnalysisController{private final AnalysisService s;public AnalysisController(AnalysisService x){s=x;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Response save(@AuthenticationPrincipal CurrentUser u,@Valid@RequestBody Create d){return s.save(u.id(),d);}@GetMapping public List<Response> list(@AuthenticationPrincipal CurrentUser u){return s.list(u.id());}@GetMapping("/{id}")public Response get(@AuthenticationPrincipal CurrentUser u,@PathVariable String id){return s.get(u.id(),id);}}
